*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Inter",
    Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 17px;
  line-height: 1.6;
  color: var(--ink);
  background: var(--bg);
}

.wrap {
  max-width: 720px;
  margin: 0 auto;
  padding: 0 20px;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 8px;
  top: -40px;
  background: var(--ink);
  color: var(--bg);
  padding: 8px 12px;
  border-radius: 8px;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus {
  top: 8px;
}

/* Header */
.site-header {
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}
.site-header .wrap {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-top: 16px;
  padding-bottom: 16px;
}
.brand {
  font-size: 22px;
  line-height: 1;
}
.brand-name {
  margin: 0;
  font-weight: 600;
  letter-spacing: 0.01em;
}

/* Hero */
.hero {
  padding: 56px 0 32px;
  text-align: left;
}
.eyebrow {
  margin: 0 0 8px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 13px;
  font-weight: 600;
  color: var(--accent);
}
@media (prefers-color-scheme: dark) {
  .eyebrow { color: var(--accent); }
}
h1 {
  margin: 0 0 12px;
  font-size: clamp(2rem, 4vw + 1rem, 2.75rem);
  line-height: 1.15;
  letter-spacing: -0.02em;
}
.lede {
  margin: 0;
  color: var(--muted);
  font-size: 1.05rem;
  max-width: 52ch;
}

/* FAQ list */
.faq {
  padding: 24px 0 64px;
  display: grid;
  gap: 12px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.example {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: border-color 150ms ease;
}

.example:has(.faq-trigger[aria-expanded="true"]) {
  border-color: color-mix(in srgb, var(--accent) 50%, var(--border));
}

.faq-q {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 600;
}

.faq-trigger {
  appearance: none;
  width: 100%;
  background: transparent;
  border: 0;
  padding: 18px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  font: inherit;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  min-height: 44px;
}

.faq-trigger:hover {
  background: color-mix(in srgb, var(--accent) 6%, transparent);
}

.faq-trigger:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}

.faq-trigger-text {
  flex: 1;
}

/* Chevron icon — drawn with CSS so it inherits currentColor */
.faq-icon {
  flex: 0 0 auto;
  width: 24px;
  height: 24px;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  border: 1px solid var(--border);
  position: relative;
  transition: transform 200ms ease, background-color 200ms ease,
              border-color 200ms ease;
}
.faq-icon::before {
  content: "";
  width: 8px;
  height: 8px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: translateY(-2px) rotate(45deg);
  transition: transform 200ms ease;
}
.faq-trigger[aria-expanded="true"] .faq-icon {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-ink);
}
.faq-trigger[aria-expanded="true"] .faq-icon::before {
  transform: translateY(2px) rotate(-135deg);
}

/* Panel */
.details {
  padding: 0 20px 20px;
  color: var(--ink-soft);
  border-top: 1px solid var(--border);
}
.details[hidden] {
  display: none;
}
.details > :first-child { margin-top: 16px; }
.details > :last-child { margin-bottom: 0; }

/* Footer */
.site-footer {
  border-top: 1px solid var(--border);
  padding: 24px 0 32px;
  color: var(--muted);
  font-size: 0.9rem;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition: none !important;
    animation: none !important;
  }
}

/* Forced colors / Windows high contrast */
@media (forced-colors: active) {
  .example {
    border: 1px solid CanvasText;
  }
  .faq-trigger:focus-visible {
    outline-color: Highlight;
  }
  .faq-icon {
    border-color: CanvasText;
  }
  .faq-trigger[aria-expanded="true"] .faq-icon {
    background: Highlight;
    color: HighlightText;
    border-color: Highlight;
  }
}
